class SortColors {
  public void solve(char[] arr) {
    // Count occurrences of each color
    int rCount = 0;
    int wCount = 0;
    for (char c : arr) {
      if (c == 'R') rCount++;
      if (c == 'W') wCount++;
    }

    // Rewrite array with the right number of each color
    int i = 0;
    while (rCount-- > 0) {
      arr[i++] = 'R';
    }
    while (wCount-- > 0) {
      arr[i++] = 'W';
    }
    while (i < arr.length) {
      arr[i++] = 'B';
    }

  }
}

